// Eval harness: one task case = (input, reference, scorers). Run, score, aggregate.
export interface EvalCase {
  id: string;
  input: string;
  reference?: unknown;
  scorers: ('task_success' | 'tool_accuracy' | 'cost' | 'safety' | 'trajectory_similarity')[];
}

export interface EvalResult {
  caseId: string;
  scores: Record<string, number>;
  trace: { steps: number; tokensIn: number; tokensOut: number; ms: number };
  pass: boolean;
}

export async function runEvalSet(
  cases: EvalCase[],
  runAgent: (input: string) => Promise<{ final: string; trajectory: unknown[]; usage: { in: number; out: number; ms: number } }>,
  scorers: Record<string, (case_: EvalCase, run: Awaited<ReturnType<typeof runAgent>>) => Promise<number>>,
  threshold = 0.7,
): Promise<{ results: EvalResult[]; summary: Record<string, number> }> {
  const results: EvalResult[] = [];
  for (const c of cases) {
    const run = await runAgent(c.input);
    const scores: Record<string, number> = {};
    for (const name of c.scorers) scores[name] = await scorers[name](c, run);
    const avg = Object.values(scores).reduce((a, b) => a + b, 0) / Object.values(scores).length;
    results.push({
      caseId: c.id,
      scores,
      trace: { steps: run.trajectory.length, tokensIn: run.usage.in, tokensOut: run.usage.out, ms: run.usage.ms },
      pass: avg >= threshold,
    });
  }
  const summary = {
    passRate: results.filter(r => r.pass).length / results.length,
    p50Steps: percentile(results.map(r => r.trace.steps), 0.5),
    p90Cost: percentile(results.map(r => r.trace.tokensIn + r.trace.tokensOut), 0.9),
  };
  return { results, summary };
}

function percentile(xs: number[], q: number) {
  const sorted = [...xs].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length * q)] ?? 0;
}
